<section class="detail-intro"><div class="container"><nav class="breadcrumb" aria-label="Caminho"><a href="<?=url('vitrine')?>">Projetos</a><span>/</span><a href="<?=url('vitrine?edicao='.$project['edicao_id'])?>"><?=e($project['edicao'])?></a><span>/</span><span><?=e($project['area'])?></span></nav><div class="detail-badges"><span class="badge"><?=e($project['area'])?></span><?php if($project['destaque']):?><span class="badge warm">Projeto em destaque</span><?php endif;?></div><h1><?=e($project['titulo'])?></h1><p class="detail-subtitle"><?=e($project['curso'])?> · <?=e($project['ano'])?></p><div class="detail-actions"><form method="post" action="<?=url('favoritar/'.$project['id'])?>"><?=csrfField()?><button class="button secondary"><?=$favorite?'♥ Salvo nos favoritos':'♡ Salvar projeto'?></button></form><button class="button secondary" data-share="<?=e(url('projeto/'.$project['id']))?>">Compartilhar ↗</button><button class="button secondary" data-print>Salvar em PDF</button><span id="share-status" role="status"></span></div></div></section>
<div class="container detail-grid section"><article class="detail-body"><?php $images=array_filter($project['arquivos'],fn($a)=>str_starts_with($a['mime'],'image/'));if($images):?><section class="gallery" aria-label="Galeria de imagens"><?php foreach($images as $image):?><figure><a href="<?=url('arquivo/'.$image['id'])?>" target="_blank" rel="noopener"><img src="<?=url('arquivo/'.$image['id'])?>" alt="<?=e($image['texto_alternativo'])?>" loading="lazy"></a><figcaption><?=e($image['texto_alternativo'])?></figcaption></figure><?php endforeach;?></section><?php endif;?><section><div class="eyebrow">A IDEIA POR TRÁS DO PROJETO</div><h2>Resumo</h2><div class="prose"><?=nl2br(e($project['resumo']))?></div></section><section><h2>Objetivos</h2><div class="prose"><?=nl2br(e($project['objetivos']))?></div></section><section><h2>Palavras que conectam</h2><div class="tags"><?php foreach($project['palavras'] as $word):?><a href="<?=url('vitrine?q='.rawurlencode($word['nome']))?>"><?=e($word['nome'])?></a><?php endforeach;?></div></section>
<?php $pdfs=array_filter($project['arquivos'],fn($a)=>$a['mime']==='application/pdf');if($pdfs):?><section><h2>Documentos do projeto</h2><?php foreach($pdfs as $pdf):?><div class="document-card"><div><strong><?=e($pdf['texto_alternativo'])?></strong><small>PDF · <?=round($pdf['tamanho']/1024)?> KB</small></div><a href="<?=url('arquivo/'.$pdf['id'])?>" target="_blank" rel="noopener">Visualizar ↗</a><a href="<?=url('arquivo/'.$pdf['id'].'?download=1')?>">Baixar ↓</a></div><iframe class="pdf-frame" src="<?=url('arquivo/'.$pdf['id'])?>" title="<?=e($pdf['texto_alternativo'])?>" loading="lazy"></iframe><?php endforeach;?></section><?php endif;?>
<?php $videos=array_filter($project['links'],fn($v)=>$v['tipo']==='video' && UploadService::embedUrl($v['url']));if($videos):?><section class="videos"><h2>Apresentações em vídeo</h2><p>Vídeos externos são carregados apenas após sua escolha.</p><?php foreach($videos as $video): $embed=UploadService::embedUrl($video['url']);?><div class="video-consent"><button class="button secondary" data-video="<?=e($embed)?>" data-title="<?=e($video['titulo'])?>">Carregar <?=e($video['titulo'])?></button></div><?php endforeach;?></section><?php endif;?><?php if($project['links']):?><section><h2>Explore mais</h2><?php foreach($project['links'] as $link):?><a class="external-card" href="<?=e($link['url'])?>" target="_blank" rel="noopener noreferrer"><div><small><?=$link['tipo']==='video'?'VÍDEO DE APRESENTAÇÃO':'LINK COMPLEMENTAR'?></small><strong><?=e($link['titulo'])?></strong></div><span>↗</span></a><?php endforeach;?></section><?php endif;?></article>
<aside class="project-aside"><div class="info-panel"><div class="eyebrow">QUEM FAZ ACONTECER</div><h2>Equipe do projeto</h2><?php foreach($project['autores'] as $author):?><div class="person"><span class="avatar"><?=e(mb_substr($author['nome'],0,1))?></span><div><strong><?=e($author['nome'])?></strong><small>Autor(a) · <?=e($author['instituicao']??'')?></small><?php if($author['biografia']):?><p><?=e($author['biografia'])?></p><?php endif;?></div></div><?php endforeach;?><hr><h3>Professor responsável</h3><p><?=e($project['responsavel'])?></p><?php if($project['responsavel_bio']):?><small><?=e($project['responsavel_bio'])?></small><?php endif;?><?php if($project['colaboradores']):?><h3>Professores colaboradores</h3><?php foreach($project['colaboradores'] as $o):?><p><?=e($o['nome'])?></p><small><?=e($o['instituicao']??'')?></small><?php if($o['biografia']):?><p><?=e($o['biografia'])?></p><?php endif;?><?php endforeach;endif;?><hr><dl><dt>Instituição</dt><dd><?=e($project['instituicao'])?><small><?=e($project['cidade'].' / '.$project['uf'])?></small></dd><dt>Curso</dt><dd><?=e($project['curso'])?></dd><dt>Unidade curricular</dt><dd><?=e($project['unidade_curricular'])?></dd><dt>Área / subárea</dt><dd><?=e($project['area'])?><?= $project['subarea']?' / '.e($project['subarea']):''?></dd><dt>Edição</dt><dd><?=e($project['edicao'])?></dd></dl><div class="view-count"><?=$project['visualizacoes']?> visualizações por sessão</div><small class="identifier">ID: <?=e($project['identificador'])?></small></div></aside></div>
